import { Component, inject, signal, computed, resource } from '@angular/core';
import { DatePipe } from '@angular/common';
import { Router } from '@angular/router';
import { SolicitudService } from '../../../../shared/services/solicitud.service';
import { NavigationHistoryService } from '../../../../services/navigation-history.service';
import {
  machoteBadgeTexto,
  machoteBadgeClass,
} from '../../../../shared/utils/machote-badge.util';
import { firstValueFrom } from 'rxjs';
import { PaginatorComponent } from '../../../../shared/components/paginator/paginator.component';

@Component({
  selector: 'app-mis-evaluaciones',
  imports: [PaginatorComponent, DatePipe],
  template: `
    <div class="container py-4">
      <div class="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h4 class="mb-1 fw-bold">Mis Evaluaciones</h4>
          <p class="text-muted mb-0 small">
            Solicitudes de trámite asignadas a tu usuario para revisión técnica y dictamen.
          </p>
        </div>
      </div>

      <div class="card mb-3 shadow-sm border-0">
        <div class="card-body">
          <div class="row g-3">
            <div class="col-md-8">
              <input
                type="text"
                class="form-control"
                placeholder="Buscar por folio o solicitante..."
                [value]="searchTerm()"
                (input)="onSearchInput($event)"
              />
            </div>
            <div class="col-md-4">
              <select
                class="form-select"
                [value]="statusFilter()"
                (change)="onStatusChange($event)"
              >
                <option value="Todos">Todos los estados</option>
                <option value="Enviada">Enviada</option>
                <option value="Incompleta">Incompleta</option>
                <option value="Subsanada">Subsanada</option>
                <option value="En Análisis">En Análisis</option>
                <option value="En Firma">En Firma</option>
                <option value="Terminada">Terminada</option>
                <option value="No Autorizada">No Autorizada</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      @if (isLoading()) {
        <div class="text-center py-5">
          <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Cargando...</span>
          </div>
        </div>
      } @else if (solicitudes().length === 0) {
        <div class="card border-0 shadow-sm">
          <div class="card-body text-center py-5 text-muted">
            No tienes solicitudes de trámite asignadas.
          </div>
        </div>
      } @else {
        <div class="card border-0 shadow-sm">
          <div class="table-responsive">
            <table class="table table-hover align-middle mb-0">
              <thead class="table-light">
                <tr>
                  <th>Folio</th>
                  <th>Solicitante</th>
                  <th>Proyecto / Trámite</th>
                  <th>Fecha Recepción</th>
                  <th>Status</th>
                  <th>Machote</th>
                  <th class="text-end">Acción</th>
                </tr>
              </thead>
              <tbody>
                @for (solicitud of solicitudes(); track solicitud.id) {
                  <tr>
                    <td>
                      <a
                        href="javascript:void(0)"
                        (click)="verDetalle(solicitud.folio)"
                        class="text-decoration-none fw-bold"
                      >
                        {{ solicitud.folio }}
                      </a>
                    </td>
                    <td>{{ solicitud.solicitante }}</td>
                    <td>{{ solicitud.proyecto || '—' }}</td>
                    <td>{{ solicitud.fechaRecepcion }}</td>
                    <td>
                      <span class="badge" [class]="statusBadgeClass(solicitud.status)">
                        {{ solicitud.status }}
                      </span>
                    </td>
                    <td>
                      <span class="badge" [class]="machoteBadgeClass(solicitud.ultimoMachote)"
                        [title]="solicitud.ultimoMachote?.motivo ?? ''">
                        {{ machoteBadgeTexto(solicitud.ultimoMachote) }}
                      </span>
                      @if (solicitud.ultimoMachote; as machote) {
                        <span class="text-muted ms-2 small">
                          v{{ machote.version }} · {{ machote.createdAt | date:'shortDate' }}
                        </span>
                      }
                    </td>
                    <td class="text-end">
                      <button
                        class="btn btn-outline-primary btn-sm"
                        (click)="verDetalle(solicitud.folio)"
                      >
                        Ver detalle
                      </button>
                    </td>
                  </tr>
                }
              </tbody>
            </table>
          </div>
        </div>

        @if (paginationMeta().lastPage > 1) {
          <div class="mt-3">
            <app-paginator
              [currentPage]="paginationMeta().currentPage"
              [lastPage]="paginationMeta().lastPage"
              [total]="paginationMeta().total"
              [perPage]="paginationMeta().perPage"
              (pageChange)="onPageChange($event)"
            />
          </div>
        }
      }
    </div>
  `,
})
export class MisEvaluacionesComponent {
  private readonly router = inject(Router);
  private readonly solicitudService = inject(SolicitudService);
  private readonly navHistory = inject(NavigationHistoryService);

  readonly searchTerm = signal('');
  readonly statusFilter = signal('Todos');
  readonly page = signal(1);
  readonly perPage = signal(15);

  readonly queryParams = computed(() => ({
    search: this.searchTerm().trim() || undefined,
    status: this.statusFilter() === 'Todos' ? undefined : this.statusFilter(),
    page: this.page(),
    perPage: this.perPage(),
  }));

  readonly solicitudesResource = resource({
    params: () => this.queryParams(),
    loader: async ({ params }) => {
      return firstValueFrom(this.solicitudService.getMisEvaluaciones(params));
    },
  });

  readonly solicitudes = computed(() =>
    this.solicitudesResource.hasValue() ? this.solicitudesResource.value()!.data : [],
  );

  readonly paginationMeta = computed(() => {
    const v = this.solicitudesResource.value();
    return v
      ? { currentPage: v.current_page, lastPage: v.last_page, total: v.total, perPage: v.per_page }
      : { currentPage: 1, lastPage: 1, total: 0, perPage: 15 };
  });

  readonly isLoading = computed(() => this.solicitudesResource.isLoading());

  onSearchInput(event: Event): void {
    this.searchTerm.set((event.target as HTMLInputElement).value);
    this.page.set(1);
  }

  onStatusChange(event: Event): void {
    this.statusFilter.set((event.target as HTMLSelectElement).value);
    this.page.set(1);
  }

  onPageChange(page: number): void {
    this.page.set(page);
  }

  verDetalle(folio: string): void {
    this.navHistory.recordBackPath('tramites/mis-evaluaciones');
    this.router.navigate(['/ejecutivos/solicitudes', folio], {
      queryParams: { from: 'tramites/mis-evaluaciones' },
    });
  }

  machoteBadgeTexto = machoteBadgeTexto;
  machoteBadgeClass = machoteBadgeClass;

  statusBadgeClass(status: string): string {
    switch (status) {
      case 'Enviada':
        return 'bg-info text-dark';
      case 'En Análisis':
        return 'bg-primary-subtle text-primary border border-primary';
      case 'Incompleta':
        return 'bg-secondary';
      case 'Subsanada':
        return 'bg-warning text-dark';
      case 'En Firma':
        return 'bg-warning-subtle text-warning border border-warning';
      case 'Terminada':
      case 'Aprobada':
        return 'bg-success';
      case 'No Autorizada':
      case 'No Aprobada':
        return 'bg-danger';
      default:
        return 'bg-secondary';
    }
  }
}
